import math, random
from quantum_circuit import Circuit

ZERO_NOISE = {"amplitude_damping": 0.0, "phase_damping": 0.0}
def strip(p): return {k: v for k, v in p.items() if k not in ("schema_version", "noise_model")}

SINGLE_FIXED = ("x","h","y","z","s","sdg","t","tdg")
ROT = ("rx","ry","rz")
TWO_FIXED = ("cx","cz","swap")
CROT = ("crx","cry","crz")
ALL = SINGLE_FIXED + ROT + TWO_FIXED + CROT
ANGLES = (0.3, -0.7, 1.1, math.pi/2, -math.pi/3, math.pi, -math.pi,
          3*math.pi/2, 2*math.pi, -2*math.pi, 4*math.pi, 1e-13, 1e-12, 0.0)

def distinct(rng, n):
    a = rng.randrange(n); b = rng.randrange(n-1)
    if b >= a: b += 1
    return a, b

def add_gate(c, rng, kind, n):
    if kind in SINGLE_FIXED: getattr(c, kind)(rng.randrange(n))
    elif kind in ROT: getattr(c, kind)(rng.choice(ANGLES), rng.randrange(n))
    elif kind in TWO_FIXED: a,b = distinct(rng,n); getattr(c, kind)(a,b)
    else: a,b = distinct(rng,n); getattr(c, kind)(rng.choice(ANGLES), a, b)

def build(seed, case):
    rng = random.Random(f"roundtrip:{seed}:{case}")
    forced = ALL[seed % 17]
    n = rng.randint(2,4) if forced in TWO_FIXED + CROT else rng.randint(1,4)
    c = Circuit(n, n)
    add_gate(c, rng, forced, n)
    for _ in range(rng.randint(3, 8)):
        motif = rng.randrange(4)
        if motif == 0:
            pool = ALL if n >= 2 else SINGLE_FIXED + ROT
            add_gate(c, rng, rng.choice(pool), n)
        elif motif == 1:  # adjacent inverse pair
            q = rng.randrange(n)
            first = rng.choice(("x","h","y","z","s","t"))
            second = {"s":"sdg","t":"tdg"}.get(first, first)
            getattr(c, first)(q); getattr(c, second)(q)
        elif motif == 2:  # repeated rotations
            kind = rng.choice(ROT); q = rng.randrange(n)
            for _ in range(rng.randint(2,3)): getattr(c, kind)(rng.choice(ANGLES), q)
        else:  # disjoint block, shuffled
            free = list(range(n)); rng.shuffle(free)
            ops = []
            while free:
                q = free.pop()
                kind = rng.choice(SINGLE_FIXED + ROT)
                ops.append((kind, q))
            rng.shuffle(ops)
            for kind, q in ops:
                if kind in ROT: getattr(c, kind)(rng.choice(ANGLES), q)
                else: getattr(c, kind)(q)
    mode = case % 4
    if mode == 1:
        qs = rng.sample(range(n), rng.randint(1, n))
        cs = rng.sample(range(n), len(qs))
        for q, cb in zip(qs, cs): c.measure(q, cb)
    elif mode == 2:
        cs = list(range(n)); rng.shuffle(cs)
        for q in range(n): c.measure(q, cs[q])
    elif mode == 3:
        for q in range(n): c.measure(q, q)
    return c

bad_p = bad_c = 0
for seed in range(17):
    for case in range(4):
        c = build(seed, case)
        if strip(c.probabilities()) != strip(c.probabilities(noise_model=ZERO_NOISE)):
            bad_p += 1
            print("prob mismatch", seed, case)
        if strip(c.sample(shots=200, seed=seed*4+case)) != strip(c.sample(shots=200, seed=seed*4+case, noise_model=ZERO_NOISE)):
            bad_c += 1
            print("count mismatch", seed, case)
print("total:", bad_p, "prob mismatches,", bad_c, "count mismatches out of 68")
